    return powMod(a, mod - 2, mod)
}

fun powMod(a: Long, b: Int, mod: Int): Long {
    var res = 1L
    var base = a % mod
    var exp = b
    while (exp > 0) {
        if (exp % 2 == 1) {
            res = res * base % mod
        }
        base = base * base % mod
        exp /= 2
    }
    return res
}
