        if (n < 0 || k < 0 || n < k) return 0L
        return fact[n].multiply(invFact[k]).multiply(invFact[n - k]).mod(modBigInt).toLong()
    }

    // Function to compute the number of non-negative integer solutions to x1 + x2 + ... + xk = n
    fun countSolutions(n: Int, k: Int): Long {
        if (n < 0) return 0L
        return comb(n + k - 1, k - 1)
    }

    // Total number of valid states where a1 >= r and sum is s
    val totalStates = countSolutions(s - r, p)

    // If totalStates is 0, output 0 (but problem constraints ensure s >= r)
