        val remaining = s - a1
        // We need to count the number of ways to distribute 'remaining' among (p-1) players
        // such that each of them has <= a1 - 1 (since Hasan's score is a1)
        // This is equivalent to countSolutions(remaining, p-1) minus the number of solutions
        // where at least one player has >= a1

        // Use inclusion-exclusion principle
        // Number of solutions where all other players have <= a1 - 1
        var count = 0L
        for (k in 0..(p - 1)) {
