            valid = valid.add(sign.multiply(c).multiply(comb(rem2 + p - 2, p - 2)))
        }
        win = win.add(valid)
    }

    // Probability is win / total
    val qInv = total.modInverse(BigInteger.valueOf(MOD.toLong()))
    val result = win.multiply(qInv).mod(BigInteger.valueOf(MOD.toLong()))
