const val MOD = 998244353

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (p, s, r) = br.readLine().split(" ").map { it.toInt() }

    // Precompute factorials and inverse factorials up to s
    val maxN = s
    val fact = LongArray(maxN + 1)
    val invFact = LongArray(maxN + 1)
    fact[0] = 1
    for (i in 1..maxN) {
        fact[i] = fact[i - 1] * i % MOD
    }
    invFact[maxN] = modInverse(fact[maxN], MOD)
    for (i in maxN - 1 downTo 0) {
        invFact[i] = invFact[i + 1] * (i + 1) % MOD
    }

    // Precompute combinations C(n, k)
    fun comb(n: Int, k: Int): Long {
        if (n < 0 || k < 0 || n < k) return 0L
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD
    }

    // Precompute inverse of p
    val invP = modInverse(p.toLong(), MOD)

    // Compute total number of valid sequences
    var total = 0L
    for (a1 in r..s) {
        val rem = s - a1
        if (rem < 0) continue
        // Number of non-negative solutions to a2 + ... + ap = rem
        val ways = comb(rem + p - 2, p - 2)
        total = (total + ways) % MOD
    }

    // Compute winning sequences
    var win = 0L
    for (a1 in r..s) {
        val rem = s - a1
        if (rem < 0) continue
        // Case 1: a1 > all others (each ai <= a1 - 1)
        val maxOthers = a1 - 1
        if (maxOthers >= 0) {
            val ways1 = countBounded(rem, p - 1, maxOthers)
            win = (win + ways1) % MOD
        }
        // Case 2: a1 == max, count sequences where at least one ai == a1
        val waysAll = comb(rem + p - 2, p - 2)
        val waysLess = countBounded(rem, p - 1, a1 - 1)
        val waysTie = (waysAll - waysLess + MOD) % MOD
        val contribution = waysTie * invP % MOD
        win = (win + contribution) % MOD
    }

    // Compute probability
    val invTotal = modInverse(total, MOD)
    val result = win * invTotal % MOD
    println(result)
}

fun modInverse(a: Long, mod: Long): Long {
    return powMod(a, mod - 2, mod)
}

fun powMod(a: Long, b: Long, mod: Long): Long {
    var res = 1L
    var base = a % mod
    var exp = b
    while (exp > 0) {
        if (exp % 2 == 1L) {
            res = res * base % mod
        }
        base = base * base % mod
        exp /= 2
    }
    return res
}

fun countBounded(n: Int, k: Int, m: Int): Long {
    if (n < 0) return 0L
    if (k == 0) return if (n == 0) 1L else 0L
    var res = 0L
    var sign = 1L
    var term = 1L
    for (i in 0..k) {
        if (n - i * (m + 1) < 0) break
        val c = comb(k, i) * comb(n - i * (m + 1) + k - 1, k - 1) % MOD
        res = (res + sign * c) % MOD
        sign = -sign
    }
    return (res + MOD) % MOD
}

