        if (n < 0 || k < 0 || n < k) return 0L
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD
    }

    fun modInverse(a: Long, m: Long): Long {
        return BigInteger.valueOf(a).modInverse(BigInteger.valueOf(m)).toLong()
    }

    // Total number of valid states
    val total = comb(s - r + p - 1, p - 1)

