            val ways = comb(rem + others - 1, others - 1)
            cnt = (cnt + sign * c * ways) % MOD
        }
        win = (win + cnt) % MOD
    }

    // Probability is win / total
    val invTotal = modInverse(total, MOD.toLong())
    val result = (win * invTotal) % MOD
    println((result + MOD) % MOD)
