fun powMod(a: Long, n: Long, mod: Long): Long {
    var res = 1L
    var base = a % mod
    var exp = n
    while (exp > 0) {
        if (exp % 2 == 1L) {
            res = res * base % mod
        }
        base = base * base % mod
        exp /= 2
    }
    return res
