fun modInverse(a: Long, mod: Long): Long {
    var a = a % mod
    var m = mod
    var y = 0L
    var x = 1L
    if (m == 1L) return 0L
    while (a > 1) {
        val quotient = a / m
        var temp = m
        m = a % m
        a = temp
        temp = y
        y = x - quotient * y
        x = temp
    }
    if (x < 0) x += mod
    return x
}
