        // Compute dp1: sum of other players' scores = remaining, each <= a1-1
        val max_val1 = a1 - 1
        val dp1 = countWays(remaining, m, max_val1)

        // Compute dp2: sum of other players' scores = remaining, each <= a1
        val max_val2 = a1
        val dp2 = countWays(remaining, m, max_val2)

        val ways_tie = dp2 - dp1

        // Contribution to numerator: dp1 * 1 + ways_tie * 1/p
        val term1 = dp1
        val term2 = ways_tie.multiply(inv_p).mod(MOD)
        val contribution = (term1.add(term2)).mod(MOD)

        numerator = numerator.add(contribution).mod(MOD)

        // Contribution to denominator: dp2
        denominator = denominator.add(dp2).mod(MOD)
    }

    // Compute result: numerator / denominator mod MOD
    val result = numerator.multiply(denominator.modInverse(MOD)).mod(MOD)
    println(result)
}

fun countWays(sum: Int, m: Int, max_val: Int): BigInteger {
    if (sum < 0) return BigInteger.ZERO
    if (m == 0) {
        return if (sum == 0) BigInteger.ONE else BigInteger.ZERO
    }
    if (max_val < 0) return BigInteger.ZERO

    // dp[i][j] = number of ways to distribute j into i players with each <= max_val
    val dp = Array(m + 1) { Array(sum + 1) { BigInteger.ZERO } }
    dp[0][0] = BigInteger.ONE

    for (i in 1..m) {
        for (j in 0..sum) {
            for (k in 0..minOf(max_val, j)) {
                dp[i][j] = dp[i][j].add(dp[i - 1][j - k])
            }
        }
    }

    return dp[m][sum]
}
