    val maxN = s
    val fact = Array(maxN + 1) { BigInteger.ONE }
    for (i in 1..maxN) {
        fact[i] = fact[i - 1] * i.toBigInteger()
    }
    val invFact = Array(maxN + 1) { BigInteger.ONE }
    invFact[maxN] = fact[maxN].modInverse(MOD)
    for (i in maxN - 1 downTo 0) {
        invFact[i] = invFact[i + 1] * (i + 1).toBigInteger()
    }

    fun comb(n: Int, k: Int): BigInteger {
        if (n < 0 || k < 0 || n < k) return BigInteger.ZERO
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD
    }

    // Total number of valid sequences
    val total = comb(s - r + p - 1, p - 1)

    // Calculate numerator (sum over all possible a1)
    var numerator = BigInteger.ZERO
    for (a1 in r..s) {
        val rem = s - a1
        if (rem < 0) continue

        // Case 1: a1 > all others (others <= a1 - 1)
        val case1 = comb(rem + p - 2, p - 2) - comb(rem - a1 + p - 2, p - 2)
        var ways = case1

        // Case 2: exactly m others have a_i = a1
        for (m in 1..p - 1) {
            if (a1 * m > rem) break
            val rem2 = rem - a1 * m
            if (rem2 < 0) continue

            val c = comb(p - 1, m)
            val stars = comb(rem2 + (p - 1 - m) - 1, (p - 1 - m) - 1)
            ways += c * stars
        }

        numerator += ways
    }

    // Compute result as (numerator / total) mod MOD
    val result = numerator * total.modInverse(MOD) % MOD
    println(result)
}
