import java.io.BufferedReader
import java.io.InputStreamReader

const val MOD = 998244353

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (p, s, r) = br.readLine().split(" ").map { it.toInt() }

    // Precompute factorials and inverse factorials up to s + p
    val maxN = s + p
    val fact = LongArray(maxN + 1) { 1L }
    for (i in 1..maxN) {
        fact[i] = fact[i - 1] * i % MOD
    }
    val invFact = LongArray(maxN + 1) { 1L }
    invFact[maxN] = modInverse(fact[maxN], MOD)
    for (i in maxN - 1 downTo 0) {
        invFact[i] = invFact[i + 1] * (i + 1) % MOD
    }

    // Function to compute combination C(n, k)
    fun comb(n: Int, k: Int): Long {
        if (n < 0 || k < 0 || n < k) return 0L
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD
    }

    // Function to compute number of non-negative integer solutions to x1 + x2 + ... + xn = sum
    fun countSolutions(n: Int, sum: Int): Long {
        if (sum < 0) return 0L
        return comb(sum + n - 1, n - 1)
    }

    // Total number of valid states where a1 >= r and sum of all scores = s
    val totalStates = countSolutions(p, s - r)

    // Calculate winning states
    var winningStates = 0L

    // Case 1: a1 > max of others
    for (a1 in r..s) {
        val remaining = s - a1
        if (remaining < 0) break
        // Number of ways others can have scores <= a1 - 1
        // This is equivalent to countSolutions(p-1, remaining) minus countSolutions(p-1, remaining - (a1))
        val ways = (countSolutions(p - 1, remaining) - countSolutions(p - 1, remaining - a1) + MOD) % MOD
        winningStates = (winningStates + ways) % MOD
    }

    // Case 2: a1 = max of others (tie)
    for (a1 in r..s) {
        val remaining = s - a1
        if (remaining < 0) break
        // Number of ways others have scores <= a1
        val ways = countSolutions(p - 1, remaining) - countSolutions(p - 1, remaining - (a1 + 1))
        if (ways < 0) {
            // This shouldn't happen due to MOD handling, but just in case
        }
        val waysMod = (ways + MOD) % MOD
        // Number of ways others have scores <= a1 - 1
        val waysStrict = countSolutions(p - 1, remaining) - countSolutions(p - 1, remaining - a1)
        val waysStrictMod = (waysStrict + MOD) % MOD
        // Number of ways at least one other has exactly a1
        val tieWays = (waysMod - waysStrictMod + MOD) % MOD
        // Probability of winning in tie is 1 / (number of players with a1)
        // We need to sum over all possible distributions where at least one other has a1
        // For each such distribution, the probability is 1 / (1 + count of others with a1)
        // This is complex, so we use inclusion-exclusion or another approach
        // Alternative: sum over k (number of others with a1) from 1 to p-1
        // For each k, compute number of ways where exactly k others have a1, and rest have <= a1 - 1
        // Then multiply by 1/(k+1)
        for (k in 1..(p - 1)) {
            // Choose k others to have a1
            val chooseK = comb(p - 1, k)
            // Remaining sum after assigning a1 to k others
            val remSum = remaining - k * a1
            if (remSum < 0) break
            // Number of ways for remaining (p-1-k) others to have scores <= a1 - 1
            val waysRest = countSolutions(p - 1 - k, remSum) - countSolutions(p - 1 - k, remSum - a1)
            val waysRestMod = (waysRest + MOD) % MOD
            val totalWays = chooseK * waysRestMod % MOD
            val prob = modInverse(k + 1L, MOD)
            winningStates = (winningStates + totalWays * prob % MOD) % MOD
        }
    }

    // Compute the result
    val invTotal = modInverse(totalStates, MOD)
    val result = winningStates * invTotal % MOD
    println(result)
