To solve this problem, we need to determine the probability that Hasan wins the TopScore game given the number of players, the total sum of scores, and Hasan's minimum score. The solution involves combinatorial mathematics and dynamic programming to count valid score distributions and compute the probability efficiently.

### Approach
1. **Problem Analysis**:
   - Hasan's score must be at least `r`, and the total sum of all players' scores is `s`.
   - We need to compute the probability that Hasan's score is the highest (or tied for the highest and chosen randomly among the top scorers).

2. **Key Insights**:
   - **Total Valid States**: Calculate the number of ways to distribute the remaining score `s - r` among all players, ensuring Hasan's score is at least `r`.
   - **Winning States**: For each possible score `a1` of Hasan (from `r` to `s`), compute the number of ways the other players can have scores such that Hasan either has the highest score or is among the top scorers.

3. **Dynamic Programming**:
   - Use dynamic programming to count the number of ways to distribute scores among other players such that their scores are within certain bounds.
   - For each possible score of Hasan, compute the probability of winning by considering all valid distributions of scores for the other players.

4. **Modular Arithmetic**:
   - Since the result needs to be computed modulo `998244353`, use modular inverses for division operations.

### Solution Code
```kotlin
import java.math.BigInteger

fun main() {
    val MOD = 998244353.toBigInteger()
    val p = readLine()!!.split(" ").map { it.toInt() }
    val players = p[0]
    val s = p[1]
    val r = p[2]

    if (players == 1) {
        println(1)
        return
    }

    // Precompute factorial and inverse factorial up to s
    val maxN = s
    val fact = Array(maxN + 1) { BigInteger.ONE }
    for (i in 1..maxN) {
        fact[i] = fact[i - 1].multiply(BigInteger.valueOf(i.toLong()))
    }

    val invFact = Array(maxN + 1) { BigInteger.ONE }
    invFact[maxN] = fact[maxN].modInverse(MOD)
    for (i in maxN - 1 downTo 0) {
        invFact[i] = invFact[i + 1].multiply(BigInteger.valueOf((i + 1).toLong())).mod(MOD)
    }

    fun comb(n: Int, k: Int): BigInteger {
        if (n < 0 || k < 0 || n < k) return BigInteger.ZERO
        return fact[n].multiply(invFact[k]).multiply(invFact[n - k]).mod(MOD)
    }

    // Compute total_states: C(s - r + p - 1, p - 1)
    val totalStatesArg = s - r + players - 1
    val totalStates = comb(totalStatesArg, players - 1)

    if (totalStates.equals(BigInteger.ZERO)) {
        println(0)
        return
    }

    var numerator = BigInteger.ZERO

    for (a1 in r..s) {
        val remaining = s - a1
        if (remaining < 0) continue

        // Compute count_less: number of ways other players have all < a1
        val m = players - 1
        val maxLess = a1 - 1
        val countLess = comb(remaining + m - 1, m - 1)
        if (maxLess >= 0) {
            // Subtract cases where any of the m players has >= a1
            // Using inclusion-exclusion
            var temp = BigInteger.ZERO
            for (k in 1..m) {
                val term = comb(m, k) * comb(remaining - k * a1 + m - 1, m - 1)
                if (k % 2 == 1) {
                    temp = temp.add(term)
                } else {
                    temp = temp.subtract(term)
                }
            }
            countLess = countLess.subtract(temp).mod(MOD)
        }

        // Compute count_ge: number of ways other players have at least one >= a1
        val countGe = comb(remaining + m - 1, m - 1).subtract(countLess).mod(MOD)

        // Compute sum_t for count_ge cases
        var sumT = BigInteger.ZERO
        for (t in 1..m) {
            val c = comb(m, t)
            val rem = remaining - t * a1
            if (rem < 0) continue
            // Number of ways for the remaining (m - t) players to have sum rem, each >=0 and <= a1 - 1
            val ways = comb(rem + (m - t) - 1, (m - t) - 1)
            var temp = BigInteger.ZERO
            for (k in 0..(m - t)) {
                val term = comb(m - t, k) * comb(rem - k * a1 + (m - t) - 1, (m - t) - 1)
                if (k % 2 == 0) {
                    temp = temp.add(term)
                } else {
                    temp = temp.subtract(term)
                }
            }
            ways = temp.mod(MOD)
            sumT = sumT.add(c.multiply(ways).multiply(BigInteger.valueOf(t.toLong()))).mod(MOD)
        }

        // Compute contribution
        val term1 = countLess.multiply(BigInteger.ONE)
        val term2 = sumT.multiply(BigInteger.ONE)
        val contribution = (term1.add(term2)).mod(MOD)
        numerator = numerator.add(contribution).mod(MOD)
    }

    val invTotal = totalStates.modInverse(MOD)
    val result = numerator.multiply(invTotal).mod(MOD)
    println(result)
}
